			'refund_review_cases' => array('uid','reference_code','purchase_id','obligation_id','evidence_id','kind','amount_minor','currency','state','academic_consequence','resolution_note','refund_review_version'),
			'refund_review_events' => array('uid','refund_review_id','event_sequence','event_type','from_state','to_state','reason_code','evidence_channel','evidence_reference_digest','evidence_at','occurred_at','recorded_at','recorded_by'),
