			array('renewal_cycles','cycle_sequence',true),array('renewal_cycle_events','cycle_sequence',true),array('renewal_cycle_commands','command_key_digest',true),
			array('collection_intents','cycle_obligation',true),array('collection_intent_events','intent_sequence',true),array('collection_intent_commands','command_key_digest',true),
			array('recovery_cases','intent_case',true),array('recovery_case_events','case_sequence',true),array('recovery_case_commands','command_key_digest',true),
			array('refund_review_cases','evidence_case',true),array('refund_review_events','review_sequence',true),array('refund_review_commands','command_key_digest',true),
			array('recurring_protections','cycle_protection',true),array('recurring_protections','claim_protection',true),array('recurring_protection_events','protection_sequence',true),array('recurring_protection_commands','command_key_digest',true),
