		if ( ! self::has_index_columns( $outbox, 'intent_version', false, array('intent_key','workflow_version') ) ) throw new \RuntimeException('Migration verification failed: platform_outbox intent index');
	}

	/**
	 * §7.3 — the row-level half of the S verifier: routing/freeze state, the frozen rule digest, the
	 * mirrored outbox schedule and the closed exhaustion partition.
	 *
	 * The checks are read-only and fail closed by code; they never repair a row.
	 */
	private static function verify_notification_authority_data():void{
		global $wpdb; $p = $wpdb->prefix . 'dzn_';
		$versions = $wpdb->get_results( "SELECT * FROM {$p}notification_workflow_versions WHERE state = 'active'" ) ?: array();
		$routed = array();
		foreach ( $versions as $version ) {
			$intent = (string) $version->intent_key;
			if ( isset( $routed[ $intent ] ) ) throw new \RuntimeException('Migration verification failed: two active versions route '.$intent);
			$routed[ $intent ] = true;
			if ( (int) $version->active_slot !== 1 || (int) $version->intent_active_slot !== 1 ) throw new \RuntimeException('Migration verification failed: active version routing slot');
			if ( $version->rule_set_digest === null || $version->rule_frozen_at === null ) throw new \RuntimeException('Migration verification failed: active version must be frozen');
			try {
				$rules = $wpdb->get_results( $wpdb->prepare( "SELECT * FROM {$p}notification_workflow_rules WHERE workflow_version_id = %d ORDER BY rule_kind,rule_code,ordinal", (int) $version->id ) ) ?: array();
				$rows = array(); foreach ( $rules as $rule ) $rows[] = array(
					'rule_kind' => (string) $rule->rule_kind, 'rule_code' => (string) $rule->rule_code, 'ordinal' => (int) $rule->ordinal,
					'parameter_a' => $rule->parameter_a, 'parameter_b' => $rule->parameter_b, 'parameter_c' => $rule->parameter_c, 'parameter_d' => $rule->parameter_d,
				);
				\Delnavazan\Platform\Core\Application\NotificationIntegrity::versionIntegrity( $version, $rows );
			} catch ( \Throwable $error ) {
				throw new \RuntimeException('Migration verification failed: active version integrity: '.$error->getMessage());
			}
		}
		// Every S-owned outbox row mirrors its notification's locked derivation, no S-owned row exists without
		// one, and the 1:1 relationship holds on **both** sides: the row must name its notification and the
		// notification's own `outbox_id` must name that same row (§6.5/§7.1).
		$rows = $wpdb->get_results( "SELECT o.id AS outbox_id,o.notification_id,o.scheduled_for,o.expires_at,o.deferral_count,o.available_at,n.id AS notification_id_check,n.outbox_id AS n_outbox,n.state,n.scheduled_for AS n_scheduled,n.expires_at AS n_expires,n.deferral_count AS n_count,(SELECT MAX(next_available_at) FROM {$p}notification_attempts a WHERE a.notification_id=n.id) AS last_rearm FROM {$p}platform_outbox o LEFT JOIN {$p}notifications n ON n.id=o.notification_id WHERE o.notification_id IS NOT NULL" ) ?: array();
		foreach ( $rows as $row ) {
			if ( $row->notification_id_check === null ) throw new \RuntimeException('Migration verification failed: orphan outbox row');
			// The reciprocal pointer is part of the row proof: a NULL aggregate pointer, or one naming a
			// different valid/legacy row, is refused even though this row mirrors its schedule exactly.
			if ( $row->n_outbox === null || (int) $row->n_outbox !== (int) $row->outbox_id ) throw new \RuntimeException('Migration verification failed: notification outbox pointer divergence');
			if ( $row->n_scheduled === null ) {
				if ( $row->scheduled_for !== null || $row->expires_at !== null || $row->deferral_count !== null ) throw new \RuntimeException('Migration verification failed: pre-scheduling mirror');
				continue;
			}
			if ( (string) $row->scheduled_for !== (string) $row->n_scheduled || (string) $row->expires_at !== (string) $row->n_expires || (int) $row->deferral_count !== (int) $row->n_count ) throw new \RuntimeException('Migration verification failed: outbox mirror divergence');
			$allowed = array( (string) $row->n_scheduled );
			if ( $row->last_rearm !== null ) $allowed[] = (string) $row->last_rearm;
			if ( ! in_array( (string) $row->available_at, $allowed, true ) ) throw new \RuntimeException('Migration verification failed: outbox available_at contract');
		}
		// §6.5/§7.1 — the same 1:1 relation stated from the aggregate side as a row-level anti-join: every
		// S-owned notification must own the one outbox row its lease/dispatch state lives on. The loop above
		// only visits rows that still name a notification, so a pair whose **both** pointers were cleared
		// would otherwise pass this verifier with no mirror row at all — the pair is refused here, with the
		// same diagnostic the shared aggregate verification reports below, instead of being read as valid.
		$unmirrored = $wpdb->get_col( "SELECT n.id FROM {$p}notifications n LEFT JOIN {$p}platform_outbox o ON o.notification_id = n.id WHERE o.id IS NULL" ) ?: array();
		if ( $unmirrored !== array() ) throw new \RuntimeException('Migration verification failed: notification without an outbox mirror: schedule_derivation_divergence');
		// §7.3 — the aggregate half of the S verifier: every S-owned notification re-derives its persisted
		// schedule from its frozen rules, resolves its tier-F instant from the persisted subject column, and
		// proves each closed attempt's closure partition and persisted retry schedule. The outbox mirror is
		// checked row-to-row just above *and* handed to the same shared aggregate verification the protected
		// reads and the dispatch claim run, so a mirrored row can never disagree with its aggregate — or go
		// missing behind one, or be a row the aggregate does not point at — and still pass verification.
		$notifications = $wpdb->get_results( "SELECT * FROM {$p}notifications" ) ?: array();
		foreach ( $notifications as $notification ) {
			try {
				$version = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$p}notification_workflow_versions WHERE id=%d", (int) $notification->workflow_version_id ) );
				if ( ! $version ) throw new \RuntimeException('workflow_version_integrity');
				$tier = \Delnavazan\Platform\Core\Application\NotificationRule::intentTier( (string) $notification->intent_key );
				$binding = \Delnavazan\Platform\Core\Application\NotificationRule::requiredBinding( (string) $notification->intent_key );
				$ruleRows = $wpdb->get_results( $wpdb->prepare( "SELECT * FROM {$p}notification_workflow_rules WHERE workflow_version_id=%d ORDER BY rule_kind,rule_code,ordinal", (int) $version->id ) ) ?: array();
				$rules = array();
				foreach ( $ruleRows as $rule ) $rules[] = array(
					'rule_kind' => (string) $rule->rule_kind, 'rule_code' => (string) $rule->rule_code, 'ordinal' => (int) $rule->ordinal,
					'parameter_a' => $rule->parameter_a, 'parameter_b' => $rule->parameter_b, 'parameter_c' => $rule->parameter_c, 'parameter_d' => $rule->parameter_d,
				);
				$composition = \Delnavazan\Platform\Core\Application\NotificationSchedule::validateComposition( array_values( array_filter( $rules, static fn(array $rule):bool => $rule['rule_kind'] === 'schedule' ) ), $tier );
				$policy = \Delnavazan\Platform\Core\Application\NotificationRetry::validatePolicy( array_values( array_filter( $rules, static fn(array $rule):bool => $rule['rule_kind'] === 'retry' ) ) );
				$subjectInstant = $tier === 'F' ? \Delnavazan\Platform\Core\Application\NotificationIntegrity::persistedInstant( (string) $binding['aggregate'], (int) $notification->subject_aggregate_id, $binding['instant'] ) : null;
				$attempts = $wpdb->get_results( $wpdb->prepare( "SELECT * FROM {$p}notification_attempts WHERE notification_id=%d ORDER BY attempt_sequence", (int) $notification->id ) ) ?: array();
				$mirror = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$p}platform_outbox WHERE notification_id=%d", (int) $notification->id ) );
				\Delnavazan\Platform\Core\Application\NotificationIntegrity::aggregateIntegrity( $notification, $composition, $policy, $subjectInstant, $mirror, $attempts, (int) $version->version_number );
			} catch ( \Throwable $error ) {
				throw new \RuntimeException('Migration verification failed: notification aggregate: '.$error->getMessage());
			}
		}
	}

