		// migration converges on the existing root instead of failing or duplicating it.
		if ( (int) $wpdb->get_var( "SELECT COUNT(*) FROM {$p}finance_policy_roots WHERE root_key='finance_policy'" ) === 0 ) {
			$old = $wpdb->suppress_errors( true );
			$wpdb->insert( $p . 'finance_policy_roots', array( 'root_key' => 'finance_policy', 'created_at' => $now, 'created_by' => null ) );
			$rootError = $wpdb->last_error;
			$wpdb->suppress_errors( $old );
			if ( (int) $wpdb->get_var( "SELECT COUNT(*) FROM {$p}finance_policy_roots WHERE root_key='finance_policy'" ) !== 1 ) throw new \RuntimeException('Migration operation failed: finance policy root: ' . $rootError);
		}
		// §13.5: the one declared seed — version 1 of the three payability/compensation keys, each active
		// from the migration instant. This is configuration this contract declares, not an inference from
		// data. `FINANCE_STATEMENT_TIMEZONE` is deliberately absent: unset is the absence of a version.
		foreach ( array( 'INTRO_PAYABILITY_POLICY' => 'non_payable', 'STUDENT_NO_SHOW_COMPENSATION_POLICY' => 'payable', 'INTERRUPTION_COMPENSATION_POLICY' => 'payable' ) as $key => $value ) {
			if ( (int) $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$p}finance_policies WHERE policy_key=%s AND policy_version=1", $key ) ) === 0 ) {
				$wpdb->insert( $p . 'finance_policies', array(
					'policy_key' => $key, 'policy_version' => 1, 'policy_value' => $value, 'value_type' => 'policy_reference',
					'effective_from' => $now, 'status' => 'active', 'reason_code' => 'phase_u_declared_default',
					'evidence_channel' => 'platform_default', 'evidence_reference_digest' => hash( 'sha256', 'phase_u_declared_default:' . $key ), 'evidence_at' => $now,
					'recorded_at' => $now, 'recorded_by' => 0, 'created_at' => $now, 'created_by' => 0, 'updated_at' => $now,
				) );
				if ( $wpdb->last_error !== '' ) throw new \RuntimeException( 'Migration operation failed: finance policy seed: ' . $wpdb->last_error );
			}
		}
	}

	/**
