		// Rule 6: the phase owns no academic, notification, payment or accounting storage.
		foreach ( array('finance_lessons','finance_terms','finance_attendance','finance_notifications','finance_payments','finance_ledger','finance_invoices','finance_payouts','finance_prices') as $forbidden ) {
			$physical = $p . $forbidden;
			if ( $wpdb->get_var( $wpdb->prepare( 'SHOW TABLES LIKE %s', $physical ) ) === $physical ) throw new \RuntimeException('Migration verification failed: Phase 2A.2-U must not own academic, notification, payment or accounting storage: '.$forbidden);
		}
		// Rule 13: exactly one global policy root, with no mutable column.
		if ( (int) $wpdb->get_var( "SELECT COUNT(*) FROM {$p}finance_policy_roots" ) !== 1 || (string) $wpdb->get_var( "SELECT root_key FROM {$p}finance_policy_roots LIMIT 1" ) !== 'finance_policy' ) throw new \RuntimeException('Migration verification failed: the global policy root must exist exactly once with root_key=finance_policy');
		foreach ( (array) $wpdb->get_col( "SHOW COLUMNS FROM {$p}finance_policy_roots" ) as $column ) if ( ! in_array( strtolower( (string) $column ), array('id','root_key','created_at','created_by'), true ) ) throw new \RuntimeException('Migration verification failed: the global policy root declares no mutable column');
		// Rule 5: no mutating statement is ever exposed by the declared storage.
		$seededPolicies = array('INTRO_PAYABILITY_POLICY','STUDENT_NO_SHOW_COMPENSATION_POLICY','INTERRUPTION_COMPENSATION_POLICY');
		$policyRows = (array) $wpdb->get_results( "SELECT * FROM {$p}finance_policies ORDER BY policy_key,policy_version" );
		foreach ( $policyRows as $row ) {
			if ( ! in_array( (string) $row->policy_key, array_merge( $seededPolicies, array('FINANCE_STATEMENT_TIMEZONE') ), true ) ) throw new \RuntimeException('Migration verification failed: a finance policy key outside the declared vocabulary: '.(string) $row->policy_key);
			if ( ! in_array( (string) $row->status, array('active','superseded','withdrawn'), true ) ) throw new \RuntimeException('Migration verification failed: a finance policy status outside the declared vocabulary');
			if ( $row->effective_from === null || (string) $row->effective_from === '' ) throw new \RuntimeException('Migration verification failed: a finance policy version always records its effective instant');
			if ( $row->policy_value === null || $row->value_type === null || (string) $row->policy_value === '' || (string) $row->value_type === '' ) throw new \RuntimeException('Migration verification failed: a null-valued policy version is not a legal unset representation');
			if ( (string) $row->reason_code !== 'phase_u_declared_default' && $row->reason_code !== null && ! self::finance_reason_code( (string) $row->policy_key, (string) $row->reason_code ) ) throw new \RuntimeException('Migration verification failed: a finance policy reason code outside its declared set');
		}
		// §13.5: the only rows migration 030 itself writes are the three declared seed versions — each the
		// migration's own (`recorded_by = 0`) version 1 of a declared seed key. A migration-authored row
		// outside that shape is a fourth seed, and a migration-authored row for the statement timezone key
		// means the deliberately unset key was seeded. A version an administrator records through §6.2's
		// commands — including the timezone key `record()` is the declared way to set (§10.5) — carries that
		// administrator as its author, is ordinary recorded history and is never counted as a seed.
		$seededShape = "policy_key IN ('INTRO_PAYABILITY_POLICY','STUDENT_NO_SHOW_COMPENSATION_POLICY','INTERRUPTION_COMPENSATION_POLICY') AND policy_version=1";
		if ( (int) $wpdb->get_var( "SELECT COUNT(*) FROM {$p}finance_policies WHERE recorded_by=0 AND NOT ({$seededShape})" ) !== 0 ) throw new \RuntimeException('Migration verification failed: a fourth seeded finance policy row');
		if ( (int) $wpdb->get_var( "SELECT COUNT(*) FROM {$p}finance_policies WHERE recorded_by=0 AND policy_key='FINANCE_STATEMENT_TIMEZONE'" ) !== 0 ) throw new \RuntimeException('Migration verification failed: the statement timezone key is never seeded');
		foreach ( $seededPolicies as $key ) if ( (int) $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$p}finance_policies WHERE policy_key=%s AND policy_version=1", $key ) ) !== 1 ) throw new \RuntimeException('Migration verification failed: the declared default policy version is missing: '.$key);
		$duplicateInstant = $wpdb->get_results( "SELECT policy_key,effective_from,COUNT(*) AS total FROM {$p}finance_policies GROUP BY policy_key,effective_from HAVING total>1" );
		if ( $duplicateInstant ) throw new \RuntimeException('Migration verification failed: two finance policy versions share one effective instant');
		// Rule 8: rate scope, state and interval invariants.
		foreach ( (array) $wpdb->get_results( "SELECT id,teacher_id,scope_kind,course_scope_id,status,active_slot,effective_from,effective_until,amount_minor,currency,rate_version FROM {$p}finance_teacher_rates" ) as $rate ) {
			$scopeOk = ( (string) $rate->scope_kind === 'teacher' && (int) $rate->course_scope_id === 0 ) || ( (string) $rate->scope_kind === 'teacher_course' && (int) $rate->course_scope_id > 0 );
			if ( ! $scopeOk ) throw new \RuntimeException('Migration verification failed: a teacher rate scope violation');
			if ( ! in_array( (string) $rate->status, array('active','superseded','withdrawn'), true ) ) throw new \RuntimeException('Migration verification failed: a teacher rate status outside the declared vocabulary');
			if ( $rate->active_slot !== null && (int) $rate->active_slot === 1 && (string) $rate->status !== 'active' ) throw new \RuntimeException('Migration verification failed: a non-active teacher rate carries the live slot');
			if ( (string) $rate->status === 'withdrawn' && ( $rate->active_slot !== null || $rate->effective_until === null ) ) throw new \RuntimeException('Migration verification failed: a withdrawn teacher rate keeps a live slot or an open interval');
			if ( (int) $rate->rate_version < 1 || (int) $rate->amount_minor < 0 ) throw new \RuntimeException('Migration verification failed: a teacher rate shape violation');
		}
		$liveRateScopes = $wpdb->get_results( "SELECT teacher_id,scope_kind,course_scope_id,COUNT(*) AS total FROM {$p}finance_teacher_rates WHERE active_slot=1 GROUP BY teacher_id,scope_kind,course_scope_id HAVING total>1" );
		if ( $liveRateScopes ) throw new \RuntimeException('Migration verification failed: two live teacher rate rows share one scope');
		$rateOverlaps = $wpdb->get_results( "SELECT a.id AS left_id,b.id AS right_id FROM {$p}finance_teacher_rates a INNER JOIN {$p}finance_teacher_rates b ON a.teacher_id=b.teacher_id AND a.scope_kind=b.scope_kind AND a.course_scope_id=b.course_scope_id AND a.id<b.id WHERE a.effective_from<COALESCE(b.effective_until,'9999-12-31 23:59:59') AND b.effective_from<COALESCE(a.effective_until,'9999-12-31 23:59:59') LIMIT 1" );
		if ( $rateOverlaps ) throw new \RuntimeException('Migration verification failed: two teacher rate intervals overlap');
		// Rule 7: statement, line, correction and evaluation shapes.
		foreach ( (array) $wpdb->get_results( "SELECT state,issued_at,issued_by,pending_line_count,period_timezone,period_label,timezone_policy_version,period_start_utc,period_end_utc FROM {$p}finance_statements" ) as $statement ) {
			if ( ! in_array( (string) $statement->state, array('draft','issued','superseded','withdrawn'), true ) ) throw new \RuntimeException('Migration verification failed: a statement state outside the declared vocabulary');
			$issued = (string) $statement->state === 'issued' || (string) $statement->state === 'superseded';
			if ( $issued !== ( $statement->issued_at !== null && $statement->issued_by !== null ) ) throw new \RuntimeException('Migration verification failed: a statement state and its issuance evidence disagree');
			if ( (string) $statement->state === 'issued' && (int) $statement->pending_line_count !== 0 ) throw new \RuntimeException('Migration verification failed: an issued statement carries a pending line');
			$triple = array( $statement->period_timezone !== null, $statement->period_label !== null, $statement->timezone_policy_version !== null );
			if ( count( array_unique( $triple ) ) !== 1 ) throw new \RuntimeException('Migration verification failed: a statement timezone triple is partially recorded');
			if ( (string) $statement->state === 'issued' && $statement->period_timezone === null ) throw new \RuntimeException('Migration verification failed: an issued statement records its timezone triple');
			if ( (string) $statement->period_end_utc <= (string) $statement->period_start_utc ) throw new \RuntimeException('Migration verification failed: a statement period is not a half-open range');
		}
		$overlappingLive = $wpdb->get_results( "SELECT a.id AS left_id,b.id AS right_id FROM {$p}finance_statements a INNER JOIN {$p}finance_statements b ON a.teacher_id=b.teacher_id AND a.id<b.id AND a.state IN ('draft','issued') AND b.state IN ('draft','issued') WHERE a.period_start_utc<b.period_end_utc AND b.period_start_utc<a.period_end_utc LIMIT 1" );
		if ( $overlappingLive ) throw new \RuntimeException('Migration verification failed: two live statements of one Teacher overlap');
		foreach ( (array) $wpdb->get_results( "SELECT line.id AS line_id,line.lesson_id AS line_lesson,snapshot.lesson_id AS snapshot_lesson,evaluation.snapshot_id AS evaluation_snapshot,line.snapshot_id AS line_snapshot FROM {$p}finance_statement_lines line LEFT JOIN {$p}finance_lesson_snapshots snapshot ON snapshot.id=line.snapshot_id LEFT JOIN {$p}finance_payability_evaluations evaluation ON evaluation.id=line.payability_evaluation_id" ) as $line ) {
			if ( $line->snapshot_lesson === null || (int) $line->line_lesson !== (int) $line->snapshot_lesson ) throw new \RuntimeException('Migration verification failed: a statement line names a snapshot of another Lesson');
			if ( $line->evaluation_snapshot === null || (int) $line->evaluation_snapshot !== (int) $line->line_snapshot ) throw new \RuntimeException('Migration verification failed: a statement line names an evaluation bound to another snapshot');
		}
		foreach ( (array) $wpdb->get_results( "SELECT correction.*,snapshot.lesson_kind AS snapshot_kind,snapshot.snapshot_instant_utc AS snapshot_instant FROM {$p}finance_snapshot_corrections correction LEFT JOIN {$p}finance_lesson_snapshots snapshot ON snapshot.id=correction.snapshot_id" ) as $correction ) {
			$half = ( $correction->intro_policy_key === null ) !== ( $correction->intro_policy_version === null );
			if ( $half ) throw new \RuntimeException('Migration verification failed: a snapshot correction carries a half-set intro policy pair');
			if ( $correction->snapshot_kind === null ) throw new \RuntimeException('Migration verification failed: a snapshot correction names a missing snapshot');
			if ( (string) $correction->snapshot_kind === 'introductory' && (string) $correction->intro_policy_key !== 'INTRO_PAYABILITY_POLICY' ) throw new \RuntimeException('Migration verification failed: a snapshot correction disagrees with the Lesson kind it corrects');
			if ( (string) $correction->snapshot_kind !== 'introductory' && $correction->intro_policy_key !== null ) throw new \RuntimeException('Migration verification failed: a non-introductory snapshot correction records an intro policy pair');
		}
		$evaluationCorruption = $wpdb->get_results( "SELECT lesson_id,COUNT(*) AS applicable FROM {$p}finance_payability_evaluations WHERE applicable_slot=1 GROUP BY lesson_id HAVING applicable>1" );
		if ( $evaluationCorruption ) throw new \RuntimeException('Migration verification failed: a Lesson carries two applicable payability evaluations');
		// Rule 11: every recorded reason/finding code is a member of its declared set.
		foreach ( (array) $wpdb->get_col( "SELECT reason_code FROM {$p}finance_exceptions WHERE reason_code IS NOT NULL" ) as $code ) if ( ! self::finance_exception_reason( (string) $code ) ) throw new \RuntimeException('Migration verification failed: a finance exception reason code outside its declared set: '.(string) $code);
		foreach ( (array) $wpdb->get_col( "SELECT finding_code FROM {$p}finance_reconciliation_findings" ) as $code ) if ( ! self::finance_finding_code( (string) $code ) ) throw new \RuntimeException('Migration verification failed: a reconciliation finding code outside its declared set: '.(string) $code);
		// Rule 14: no policy version may have stolen the coverage of a recorded dependent Finance fact.
		$coverages = array();
		foreach ( (array) $wpdb->get_results( "SELECT snapshot.intro_policy_key AS policy_key,snapshot.intro_policy_version AS policy_version,snapshot.snapshot_instant_utc AS consumed_instant FROM {$p}finance_lesson_snapshots snapshot WHERE snapshot.intro_policy_key IS NOT NULL" ) as $fact ) $coverages[] = $fact;
		foreach ( (array) $wpdb->get_results( "SELECT correction.intro_policy_key AS policy_key,correction.intro_policy_version AS policy_version,snapshot.snapshot_instant_utc AS consumed_instant FROM {$p}finance_snapshot_corrections correction INNER JOIN {$p}finance_lesson_snapshots snapshot ON snapshot.id=correction.snapshot_id WHERE correction.intro_policy_key IS NOT NULL" ) as $fact ) $coverages[] = $fact;
		foreach ( (array) $wpdb->get_results( "SELECT evaluation.policy_key AS policy_key,evaluation.policy_version AS policy_version,snapshot.snapshot_instant_utc AS consumed_instant FROM {$p}finance_payability_evaluations evaluation INNER JOIN {$p}finance_lesson_snapshots snapshot ON snapshot.id=evaluation.snapshot_id WHERE evaluation.policy_key IS NOT NULL" ) as $fact ) $coverages[] = $fact;
		foreach ( (array) $wpdb->get_results( "SELECT 'FINANCE_STATEMENT_TIMEZONE' AS policy_key,statement.timezone_policy_version AS policy_version,statement.created_at AS consumed_instant FROM {$p}finance_statements statement WHERE statement.timezone_policy_version IS NOT NULL" ) as $fact ) $coverages[] = $fact;
		foreach ( $coverages as $fact ) {
			$recorded = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$p}finance_policies WHERE policy_key=%s AND policy_version=%d", (string) $fact->policy_key, (int) $fact->policy_version ) );
			if ( ! $recorded ) throw new \RuntimeException('Migration verification failed: a recorded Finance fact names a policy version that does not exist');
			if ( (string) $recorded->effective_from > (string) $fact->consumed_instant ) throw new \RuntimeException('Migration verification failed: a recorded Finance fact names a policy version that does not cover its instant');
			$outCovering = (int) $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$p}finance_policies WHERE policy_key=%s AND effective_from>%s AND effective_from<=%s", (string) $fact->policy_key, (string) $recorded->effective_from, (string) $fact->consumed_instant ) );
			if ( $outCovering > 0 ) throw new \RuntimeException('Migration verification failed: a policy version out-covers a recorded dependent Finance fact');
		}
	}

	/** §5.4: the declared reason-code views, mirrored for the verifier without loading the application layer. */
	private static function finance_exception_reason(string $code):bool{
		return in_array( $code, array(
			'finance_vocabulary_member_not_allowed','finance_parent_not_declared','finance_parent_not_live','finance_policy_key_not_allowed',
			'finance_policy_version_conflict','finance_policy_effective_from_missing','finance_policy_value_type_invalid','finance_policy_timeline_overlap',
			'policy_effective_from_precedes_recorded_consumption','finance_policy_unset','policy_unset_for_statement_period','rate_missing_for_lesson',
			'ambiguous_teacher_rate','teacher_rate_timeline_overlap','teacher_rate_timeline_gap','teacher_rate_state_not_resolvable','rate_scope_violation',
			'rate_referenced_by_snapshot','rate_effective_from_precedes_snapshot','occurrence_anchor_missing','finance_lesson_kind_not_allowed',
			'finance_amount_not_exact','snapshot_lesson_not_finalised','snapshot_missing_for_lesson','snapshot_derivation_mismatch','snapshot_correction_incomplete',
			'command_replay_conflict','payability_pending','payability_conflicts_with_delivery_fact','payability_supersession_conflict',
			'payability_override_target_invalid','statement_period_too_long','statement_period_not_elapsed','statement_period_overlap',
			'statement_state_transition_conflict','statement_supersession_required','statement_totals_mismatch','statement_derivation_mismatch',
			'statement_timezone_representation_invalid','lesson_stated_twice','lesson_not_finalised_in_period','currency_mismatch_for_statement','upstream_aggregate_invalid',
		), true );
	}
	/** §5.2.1: the declared reconciliation finding-code view. */
	private static function finance_finding_code(string $code):bool{
		return in_array( $code, array(
			'lesson_missing_from_statement','lesson_stated_twice','lesson_not_finalised_in_period','line_amount_differs_from_recomputation',
			'statement_totals_mismatch','statement_derivation_mismatch','snapshot_missing_for_lesson','snapshot_derivation_mismatch','rate_missing_for_snapshot',
			'teacher_rate_timeline_overlap','teacher_rate_timeline_gap','payability_pending','payability_conflicts_with_delivery_fact',
			'currency_mismatch_for_statement','statement_period_overlap','lesson_archived_after_issue','delivery_outcome_changed_after_issue',
			'snapshot_corrected_after_issue','override_applied','legacy_flag_differs','provider_evidence_unmatched',
		), true );
	}
	/** §5.2.1: a version/correction/event reason is an operator reason or a declared exception reason. */
	private static function finance_reason_code(string $key,string $code):bool{
		if ( in_array( $code, array('phase_u_declared_default','operator_recorded_error','operator_decision','operator_evidence_correction'), true ) ) return true;
		return self::finance_exception_reason( $code );
	}

}
